<script setup lang="ts">import {ref,computed} from 'vue';import PageHeading from '../components/common/PageHeading.vue';import Table from '../components/common/Table.vue';import Notice from '../components/common/Notice.vue';import {sourceApi} from '../api/source';import {useTask} from '../hooks/useTask';const p=defineProps<{studies:any[];specimens:any[];votes:any[];user:any;reloadSource:()=>Promise<void>}>();const id=ref(0),study=computed(()=>p.studies.find(s=>s.id===(id.value||p.studies[0]?.id))),items=computed(()=>p.specimens.filter(s=>s.study_id===study.value?.id)),task=useTask();const example={name:'交错缺票面板手算输入',filename:'sx-missing-votes-example.json',description:'允许缺票试样保存；缺票不是类别，三人κ仅用齐票试样',categories:['砂岩','泥岩'],raters:['A','B','C'],specimens:[{reference:'MV-1',description:'齐票试样',votes:[{rater:'A',category:'砂岩'},{rater:'B',category:'砂岩'},{rater:'C',category:'砂岩'}]},{reference:'MV-2',description:'C缺票，仅参与A/B成对口径',votes:[{rater:'A',category:'砂岩'},{rater:'B',category:'泥岩'}]},{reference:'MV-3',description:'A缺票，仅参与B/C成对口径',votes:[{rater:'B',category:'泥岩'},{rater:'C',category:'泥岩'}]},{reference:'MV-4',description:'B缺票，仅参与A/C成对口径',votes:[{rater:'A',category:'泥岩'},{rater:'C',category:'砂岩'}]}]};const raw=ref(JSON.stringify(example,null,2));const vote=(item:any,r:string)=>p.votes.find(v=>v.specimen_id===item.id&&v.rater===r);const missingCount=computed(()=>items.value.length*3-p.votes.filter(v=>items.value.some(i=>i.id===v.specimen_id)).length);async function saveVote(v:any,e:Event){await task.act(async()=>{await sourceApi.editVote(v.id,(e.target as HTMLSelectElement).value);await p.reloadSource()},'逐票修订已保存，既有运行保留冻结结果')}async function create(){await task.act(async()=>{const s=await sourceApi.create(JSON.parse(raw.value));await p.reloadSource();id.value=s.id},'研究已保存（缺票试样保留，缺票不计入类别）')}function annotate(s:any){const d=prompt('试样说明',s.description);if(d!==null)task.act(async()=>{await sourceApi.editSpecimen(s.id,d);await p.reloadSource()},'试样说明已保存')}</script><template><PageHeading index="02" title="逐票核对，缺票留痕不顶类。" description="缺票试样可以保存；缺票不是类别，三人Fleiss κ只用齐票试样，成对Cohen κ只用两人共同有票的试样。"/><label>来源研究<select :value="study?.id||0" @change="id=Number(($event.target as HTMLSelectElement).value)"><option v-for="s in studies" :key="s.id" :value="s.id">{{s.name}}</option></select></label><p v-if="study">{{study.filename}} / {{study.description}}<br/>面板 {{study.raters.join(' / ')}} · 类别 {{study.categories.join(' / ')}} · 缺票 {{missingCount}} 张</p><div class="source-layout"><section><h2>逐票底稿 / 前16试样（缺票显式标注）</h2><Table :headers="['试样',...(study?.raters||[]),'说明']"><tr v-for="item in items.slice(0,16)" :key="item.id"><td>{{item.reference}}</td><td v-for="r in study?.raters" :key="r"><select v-if="user.role!=='viewer'&&vote(item,r)" :aria-label="'类别-'+vote(item,r).id" :value="vote(item,r).category" @change="saveVote(vote(item,r),$event)"><option v-for="c in study.categories" :key="c">{{c}}</option></select><span v-else-if="vote(item,r)">{{vote(item,r).category}}</span><span v-else class="missing-vote">缺票</span></td><td><button v-if="user.role!=='viewer'" @click="annotate(item)">补注</button></td></tr></Table></section><section class="input-sheet"><small>STUDY WITH OPTIONAL MISSING VOTES</small><h2>导入独立试样逐票</h2><p>2–240个试样、声明2–6类和固定3人；每试样1–3票，缺票可保存且不当作类别。重复人、未知类、重复试样编号仍拒绝。</p><form v-if="user.role!=='viewer'" @submit.prevent="create"><label>研究 JSON<textarea v-model="raw" rows="20"/></label><button class="primary" :disabled="task.state.busy">保存研究（允许缺票） →</button></form><p v-else>观察员可读底稿；导入和改票由分析员处理。</p><Notice v-bind="task.state"/></section></div></template>
